public interface IProductRepository { Task<List<Product>> GetAllAsync(); }
public class EfProductRepository : IProductRepository
{
    private readonly AppDbContext _db;
    public EfProductRepository(AppDbContext db) => _db = db;
    public async Task<List<Product>> GetAllAsync() => await _db.Products.ToListAsync();
}

public class ProductsController : Controller
{
    private readonly IProductRepository _repo;
    private readonly ILogger<ProductsController> _logger;

    public ProductsController(IProductRepository repo, ILogger<ProductsController> logger)
    {
        _repo = repo;
        _logger = logger;
    }

    public async Task<IActionResult> Index()
    {
        _logger.LogInformation("Loading products");
        var products = await _repo.GetAllAsync();
        return View(products);
    }
}

public class OrderProcessingService
{
    private readonly IOrderRepository _orderRepo;
    private readonly IPaymentGateway _paymentGateway;
    private readonly IEmailSender _emailSender;

    public OrderProcessingService(
        IOrderRepository orderRepo,
        IPaymentGateway paymentGateway,
        IEmailSender emailSender)
    {
        _orderRepo = orderRepo;
        _paymentGateway = paymentGateway;
        _emailSender = emailSender;
    }

    public async Task<bool> ProcessAsync(Order order)
    {
        var paymentResult = await _paymentGateway.ChargeAsync(order.Total);
        if (!paymentResult.Succeeded) return false;

        await _orderRepo.SaveAsync(order);
        await _emailSender.SendOrderConfirmationAsync(order);
        return true;
    }
}

public class FakeOrderRepository : IOrderRepository
{
    public List<Order> Saved { get; } = new();
    public Task SaveAsync(Order order)
    {
        Saved.Add(order);
        return Task.CompletedTask;
    }
}

public class FakePaymentGateway : IPaymentGateway
{
    public bool Succeed = true;
    public Task<PaymentResult> ChargeAsync(decimal amount)
    {
        return Task.FromResult(new PaymentResult { Succeeded = Succeed });
    }
}

[Fact]
public async Task ProcessAsync_WhenPaymentSucceeds_SavesOrder()
{
    var repo = new FakeOrderRepository();
    var payment = new FakePaymentGateway();
    var service = new OrderProcessingService(repo, payment, NullFake<EmailSender>());

    await service.ProcessAsync(new Order { Total = 100m });

    repo.Saved.Should().HaveCount(1);
}
